sql:
SELECT COALESCE(SUM(o.quantity_product * p.price), 0) AS revenue_cents
FROM orders o
JOIN product p ON p.product_id = o.product_id
JOIN customers c ON c.customer_id = o.customer_id
WHERE o.date >= '2026-03-01 00:00:00'
  AND o.date <  '2026-06-01 00:00:00'
  AND (
    CAST(substr('2026-09-26', 1, 4) AS INTEGER) - CAST(substr(c.birth_date, 1, 4) AS INTEGER) = 25
    AND (
      CAST(substr('2026-09-26', 6, 2) AS INTEGER) * 100 + CAST(substr('2026-09-26', 9, 2) AS INTEGER)
    ) >= (
      CAST(substr(c.birth_date, 6, 2) AS INTEGER) * 100 + CAST(substr(c.birth_date, 9, 2) AS INTEGER)
    )
    AND (
      CAST(substr('2026-09-26', 6, 2) AS INTEGER) * 100 + CAST(substr('2026-09-26', 9, 2) AS INTEGER)
    ) < (
      CAST(substr(c.birth_date, 6, 2) AS INTEGER) * 100 + CAST(substr(c.birth_date, 9, 2) AS INTEGER)
    ) + 100
  );
